import pytest

from harness import MARIA_ALVAREZ


@pytest.mark.criterion("FERN-2/AC-3")
@pytest.mark.parametrize(
    "said",
    ["This is Maria Alvarez, born March 3rd 1980.", "This is Maria Alvarez, born 3/3/80."],
)
def test_date_of_birth_in_another_form_verifies(call, said):
    call.say(said)

    assert call.record()["patientId"] == MARIA_ALVAREZ.id

import pytest

from harness import JAMES_WHITAKER, MARIA_ALVAREZ


@pytest.mark.criterion("FERN-2/AC-5")
def test_verified_caller_hears_nothing_about_another_patient(call):
    call.verify_as(MARIA_ALVAREZ)
    reply = call.say("When is James Whitaker's next appointment?")

    assert reply.text == (
        "I'm sorry, I can only share information about the patient I've verified on this call."
    )
    assert JAMES_WHITAKER.next_appointment.spoken not in reply.text
